-- Real DVSA data, Open Government Licence v3.0. 323 centres total.
-- Pass rates: 2024-25 (Apr 2024-Mar 2025) from DRT122A (overall), DRT122C
-- (first-attempt), DRT122D (age 17-25), DRT122E (automatic gearbox).
-- Waiting times: July 2026 (latest month available) from DRT122F, which also
-- supplied each centre's region. Excludes LGV/HGV and closed centres, and
-- (fixed from the previous version) a 'National' footer row in DRT122E that
-- was wrongly imported as a pseudo test-centre.
-- A few names didn't match cleanly across DVSA's own files (inconsistent
-- qualifiers between releases) and were kept as separate rows rather than
-- guessed at: Birmingham (Cocks Moors), Chelmsford, Leeds (Colton Mill), Leeds (Fearnville), Medway Ambley Road

-- Schema migration
alter table pass_rate_stats alter column tests_conducted drop not null;
alter table pass_rate_stats alter column tests_passed drop not null;
alter table pass_rate_stats add column if not exists first_attempt_tests integer check (first_attempt_tests >= 0);
alter table pass_rate_stats add column if not exists first_attempt_passes integer check (first_attempt_passes >= 0);
alter table pass_rate_stats add column if not exists first_attempt_zero_fault_passes integer check (first_attempt_zero_fault_passes >= 0);
alter table pass_rate_stats add column if not exists automatic_tests integer check (automatic_tests >= 0);
alter table pass_rate_stats add column if not exists automatic_passes integer check (automatic_passes >= 0);

create table if not exists age_pass_rates (
  id uuid primary key default gen_random_uuid(),
  centre_id uuid not null references test_centres(id) on delete cascade,
  period_label text not null,
  age integer not null check (age between 17 and 25),
  tests_conducted integer not null check (tests_conducted >= 0),
  tests_passed integer not null check (tests_passed >= 0),
  unique (centre_id, period_label, age)
);
alter table age_pass_rates enable row level security;
drop policy if exists "public read age_pass_rates" on age_pass_rates;
create policy "public read age_pass_rates" on age_pass_rates for select using (true);
create index if not exists idx_age_pass_rates_centre on age_pass_rates(centre_id);

create table if not exists wait_time_stats (
  id uuid primary key default gen_random_uuid(),
  centre_id uuid not null references test_centres(id) on delete cascade,
  period_label text not null,
  median_wait_weeks numeric,
  weeks_to_10pct_availability numeric,
  availability_pct numeric,
  unique (centre_id, period_label)
);
alter table wait_time_stats enable row level security;
drop policy if exists "public read wait_time_stats" on wait_time_stats;
create policy "public read wait_time_stats" on wait_time_stats for select using (true);
create index if not exists idx_wait_time_stats_centre on wait_time_stats(centre_id);

delete from wait_time_stats;
delete from age_pass_rates;
delete from pass_rate_stats;
delete from reviews;
delete from test_centres;

